"""Retry policy for outbound HTTP calls made through shipclient.

Implements HTTP client standard v3, the rate limit handling rules, the
idempotency rules and the current per-service retry profiles.
"""

from datetime import datetime, timezone

RETRYABLE_STATUSES = frozenset({429, 502, 503, 504})
IDEMPOTENT_METHODS = frozenset({"GET", "HEAD", "OPTIONS", "PUT", "DELETE"})
NON_IDEMPOTENT_METHODS = frozenset({"POST", "PATCH"})

FIRST_DELAY = 0.25

# Defaults: (attempts in total, backoff cap, longest accepted Retry-After)
DEFAULT_PROFILE = (5, 8.0, 30.0)

# Current retry profiles, keyed by lower-case service name.
PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
_MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun",
           "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


def _header(headers, name):
    name = name.lower()
    for key, value in (headers or {}).items():
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _is_ascii_digits(text):
    return bool(text) and all("0" <= c <= "9" for c in text)


def _parse_http_date(text):
    # Exactly: "Wed, 16 Sep 2026 10:00:05 GMT"
    if len(text) != 29:
        return None
    if text[3:5] != ", " or text[7] != " " or text[11] != " ":
        return None
    if text[16] != " " or text[19] != ":" or text[22] != ":":
        return None
    if text[25:] != " GMT":
        return None
    if text[0:3] not in _DAYS or text[8:11] not in _MONTHS:
        return None
    day, year = text[5:7], text[12:16]
    hour, minute, second = text[17:19], text[20:22], text[23:25]
    for part in (day, year, hour, minute, second):
        if not _is_ascii_digits(part):
            return None
    try:
        return datetime(
            int(year), _MONTHS.index(text[8:11]) + 1, int(day),
            int(hour), int(minute), int(second), tzinfo=timezone.utc,
        )
    except ValueError:
        return None


def _retry_after_seconds(value, now):
    """Wait in seconds from a Retry-After value, or None if malformed."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    if _is_ascii_digits(value):
        return float(int(value))
    when = _parse_http_date(value)
    if when is None:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    # Which failures are retried.
    if status is not None and status not in RETRYABLE_STATUSES:
        return None

    # Which requests are retried.
    method = method.upper()
    if method in NON_IDEMPOTENT_METHODS:
        key = _header(request_headers, "Idempotency-Key")
        if not isinstance(key, str) or not key.strip():
            return None
    elif method not in IDEMPOTENT_METHODS:
        return None

    # Per-service settings.
    service = _header(request_headers, "X-Service")
    profile = DEFAULT_PROFILE
    if isinstance(service, str):
        profile = PROFILES.get(service.lower(), DEFAULT_PROFILE)
    max_attempts, cap, max_retry_after = profile

    if attempt >= max_attempts:
        return None

    exponent = max(attempt - 1, 0)
    delay = cap if exponent >= 32 else min(FIRST_DELAY * (2 ** exponent), cap)

    if status in (429, 503):
        raw = _header(response_headers, "Retry-After")
        if raw is not None:
            wait = _retry_after_seconds(raw, now)
            if wait is not None:
                if wait > max_retry_after:
                    return None
                return max(wait, delay)

    return delay
